import React, { Component } from 'react';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
} from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "InstagramMetadataExtractor.js";

const initialState = {
    isLoaded: true,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    urlInputValue: '',
    isProcessing: false,
};

class InstagramMetadataExtractor extends Component {

    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    reloadData() {
        this.resetStateToDefault();
    }

    componentDidMount() {
        document.title = "Instagram Metadata Extractor";
        this.pasteFromClipboard();
    }

    pasteFromClipboard = async () => {
        try {
            const text = await navigator.clipboard.readText();
            if (text) {
                this.setState({ urlInputValue: text });
            }
        } catch (err) {
            Logger(FILE_NAME, "pasteFromClipboard", "", "clipboard read failed", err);
        }
    }

    handleUrlInputChange = (event) => {
        this.setState({ urlInputValue: event.target.value });
    }

    submitInstagramForm = (event) => {
        event.preventDefault();

        const urlsRaw = this.state.urlInputValue.trim();
        if (!urlsRaw) {
            toast("❌ Please enter Instagram URL(s)");
            return;
        }

        // Support multiple URLs separated by newlines or commas
        const urls = urlsRaw.split(/[\n,]+/).map(u => u.trim()).filter(u => u.length > 0);

        let reqData = {
            urls: urls,
        };

        Logger(FILE_NAME, "submitInstagramForm", "", "reqData", reqData);

        this.setState({
            loadingModalVisible: true,
            loadingModalState: 0,
            isProcessing: true,
        });

        this.callSubmitInstagramApi(reqData);
    }

    callSubmitInstagramApi(reqData) {
        let API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/instagram/process';
        const userData = getUserDataFromLocalStorage();

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            this.setState({
                loadingModalVisible: false,
                loadingModalState: 0
            });
            if (response.status === 200) {
                return response.json().then(result => {
                    Logger(FILE_NAME, "callSubmitInstagramApi", "FETCH_1", "result", result);
                    const message = JSON.stringify(result.data) || 'Success';
                    toast(`200 : ${message}`, { autoClose: 5000 });
                });
            } else {
                return response.text().then(text => {
                    toast(response.status + " : ❌ : " + text);
                    alert(`❌ [${response.status}] ${text}`);
                    reloadPage();
                });
            }
        })
        .catch(
            (error) => {
                Logger(FILE_NAME, "callSubmitInstagramApi", "FETCH_1", "error", error);
                toast("❌ Error: " + error.message);
                alert(`❌ [Error] ${error.message}`);
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
        )
        .finally(() => {
            this.setState({ isProcessing: false });
        });
    }

    render() {
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ?
            <div>
                <h1>Instagram Metadata Extractor &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    <CButton color="secondary" className="px-4" onClick={() => this.props.history.push('/instagram')}>← Back</CButton>
                </h1>
                <br />

                <CContainer>
                <CRow className="justify-content-center">
                <CCol md="8">
                    <CCardGroup>
                    <CCard className="p-4">
                        <CCardBody>
                        <CForm onSubmit={this.submitInstagramForm}>
                            <h1>Submit Instagram URL(s) - to extract metadata</h1>
                            <p className="text-muted">Supports profile, reel, and photo URLs. Separate multiple URLs with commas or newlines.</p>
                            <CInputGroup className="mb-3">
                                <CInputGroupPrepend>
                                    <CInputGroupText>
                                    Link(s)
                                    </CInputGroupText>
                                </CInputGroupPrepend>
                                <CInput
                                    placeholder="Paste Instagram URL(s) here..."
                                    autoComplete="on"
                                    type="text"
                                    id="inputUrl"
                                    label="Instagram URL(s)"
                                    value={this.state.urlInputValue}
                                    onChange={this.handleUrlInputChange}
                                    required
                                />
                            </CInputGroup>

                            <CRow className="mb-3">
                                <CCol>
                                    <CButton
                                        color="secondary"
                                        size="sm"
                                        onClick={this.pasteFromClipboard}
                                    >
                                        📋 Paste from clipboard
                                    </CButton>
                                </CCol>
                            </CRow>

                            <CRow>
                                <CCol xs="6">
                                    <CButton
                                        color="success"
                                        className="px-4"
                                        size="lg"
                                        type="submit"
                                        disabled={this.state.isProcessing}
                                    >
                                        {this.state.isProcessing ? 'Processing...' : 'SUBMIT'}
                                    </CButton>
                                </CCol>
                                <CCol xs="6" className="text-right">
                                    <CButton color="danger" className="px-0" onClick={() => this.reloadData()}>&nbsp;Reset&nbsp;</CButton>
                                </CCol>
                            </CRow>
                        </CForm>
                        </CCardBody>
                    </CCard>
                    </CCardGroup>
                </CCol>
                </CRow>
                </CContainer>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
                <ToastContainer
                    position="bottom-right"
                    autoClose={20000}
                    /*style={{ width: "50%", fontSize: "13px" }} */
                />
            </div>
            : <Loading />
        );
    }
}

export default InstagramMetadataExtractor;
